window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0285c6fe8b3b7f2d"]={"versions": [{"id": "FIG-0285c6fe8b3b7f2d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Baum / Feature-Dekompositionsdiagramm nach FODA-Notation (<em>Feature-Oriented Domain Analysis</em>).</li>\n<li><strong>Architektonische Einordnung:</strong> AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>, Release R24-11), Kapitel 4. Es modelliert die funktionale Dekomposition des standardisierten fahrzeugweiten Schnittstellenkonzepts (<code>Automotive_API</code>) für den Datenaustausch zwischen Fahrzeugfunktionen, High-Performance Computern (HPC) und Off-Board-/Cloud-Systemen im Kontext des <em>Software-Defined Vehicle</em> (SDV).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Feature-Entitäten:</strong></li>\n<li><code>FO_TR_FEAT_00202</code> (<strong><code>Automotive_API</code></strong>): Übergeordnetes Parent-Feature (Compound Feature). Standardisiert den generischen, domänenübergreifenden Zugriff auf Fahrzeugsignale, Sensorwerte und Aktorik-Zustände.</li>\n<li><code>FO_TR_FEAT_00203</code> (<strong><code>VISS</code></strong>): Kind-Feature. Repräsentiert die <em>Vehicle Information Service Specification</em> (W3C/COVESA-Standard). Spezifiziert das Service- und Transferprotokoll (Transport via WebSocket/HTTP, JSON-RPC/GraphQL) sowie Zugriffsoperationen (<code>get</code>, <code>set</code>, <code>subscribe</code>, <code>unsubscribe</code>).</li>\n<li><code>FO_TR_FEAT_00204</code> (<strong><code>VSS</code></strong>): Kind-Feature. Repräsentiert die <em>Vehicle Signal Specification</em> (COVESA-Standard). Definiert die hersteller- und plattformunabhängige, hierarchische Taxonomie und Semantik von Fahrzeugdaten (z. B. <code>Vehicle.Speed</code>, <code>Vehicle.Powertrain.TractionBattery.StateOfCharge</code>).</li>\n<li><strong>Beziehungen & Stereotypen:</strong></li>\n<li><strong>Dekompositionskanten mit ausgefülltem Endpunkt (Solid Dot / Mandatory Feature):</strong> Beide Sub-Features sind obligatorisch an das Parent-Feature gebunden.</li>\n<li><strong>Kardinalität/Bindung:</strong> Eine Konformität zu <code>FO_TR_FEAT_00202</code> bedingt zwingend die simultane Unterstützung von Datenmodell (<code>VSS</code>) <strong>und</strong> API-/Protokollschicht (<code>VISS</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Modell:</strong> Das Diagramm selbst enthält keine Ablaufsemantik, definiert jedoch die Systemarchitektur für folgende Laufzeitinteraktionen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Request-Handling:</strong> Ein Client (z. B. Adaptive Application oder Cloud-Agent) initiiert einen VISS-konformen Request (z. B. WebSocket-Payload).</li>\n<li><strong>Namensraum-Auflösung:</strong> Der Request referenziert den standardisierten VSS-Pfad. Der VISS-Provider/Server validiert den Pfad gegen den VSS-Katalog.</li>\n<li><strong>Plattform-Mapping:</strong> Der VISS-Server übersetzt den VSS-Datenpunkt intern auf AUTOSAR-native Kommunikationsmechanismen (<code>ara::com</code> Service-Interfaces, SOME/IP-Events, IPC oder Gateway-Mappings zu Classic-PDU-Signalen).</li>\n<li><strong>Response / Event-Stream:</strong> Asynchrone Rückmeldung oder zyklisches Publish/Subscribe über die VISS-Session an den Client.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>System- und Applikationsdesign:</strong></li>\n<li><code>Automotive_API</code> kann nicht fragmentiert umgesetzt werden: Entwickler dürfen VISS nicht mit proprietären Signalbezeichnungen betreiben, wenn AUTOSAR-Konformität zu <code>FEAT_00202</code> gefordert ist; die Semantik muss vollständig auf dem VSS-Baum basieren.</li>\n<li>Für Adaptive-Applikationen dient die Kombination aus VISS/VSS als standardisierte Abstraktionsschicht oberhalb von <code>ara::com</code>, um Applikationslogik unabhängig von OEM-spezifischen CAN/LIN/SOME/IP-Matrixen zu halten.</li>\n<li><strong>Konfiguration & Integration:</strong></li>\n<li><strong>Signal-to-Service Mapping:</strong> Ein Mapping-Layer zwischen ARXML-Signalen/Systembeschreibungen und dem VSS-Baum ist zwingend erforderlich (VSS-Mapper-Komponente auf HPC/Adaptive-Knoten).</li>\n<li><strong>Security & Access Management:</strong> VISS spezifiziert granulare Zugriffssteuerungen (Token/OAuth-basiert), die mit dem AUTOSAR Identity and Access Management (<code>ara::iam</code> / Crypto-Stack) harmonisiert werden müssen, um unberechtigten Zugriff auf steuernde VSS-Aktorikpfade zu verhindern.</li>\n</ul>"}, {"id": "FIG-c2d2cd29b330d8c8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Baum / Feature-Dekompositionsdiagramm nach FODA-Notation (<em>Feature-Oriented Domain Analysis</em>).</li>\n<li><strong>Architektonische Einordnung:</strong> AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>, Release R24-11), Kapitel 4. Es modelliert die funktionale Dekomposition des standardisierten fahrzeugweiten Schnittstellenkonzepts (<code>Automotive_API</code>) für den Datenaustausch zwischen Fahrzeugfunktionen, High-Performance Computern (HPC) und Off-Board-/Cloud-Systemen im Kontext des <em>Software-Defined Vehicle</em> (SDV).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Feature-Entitäten:</strong></li>\n<li><code>FO_TR_FEAT_00202</code> (<strong><code>Automotive_API</code></strong>): Übergeordnetes Parent-Feature (Compound Feature). Standardisiert den generischen, domänenübergreifenden Zugriff auf Fahrzeugsignale, Sensorwerte und Aktorik-Zustände.</li>\n<li><code>FO_TR_FEAT_00203</code> (<strong><code>VISS</code></strong>): Kind-Feature. Repräsentiert die <em>Vehicle Information Service Specification</em> (W3C/COVESA-Standard). Spezifiziert das Service- und Transferprotokoll (Transport via WebSocket/HTTP, JSON-RPC/GraphQL) sowie Zugriffsoperationen (<code>get</code>, <code>set</code>, <code>subscribe</code>, <code>unsubscribe</code>).</li>\n<li><code>FO_TR_FEAT_00204</code> (<strong><code>VSS</code></strong>): Kind-Feature. Repräsentiert die <em>Vehicle Signal Specification</em> (COVESA-Standard). Definiert die hersteller- und plattformunabhängige, hierarchische Taxonomie und Semantik von Fahrzeugdaten (z. B. <code>Vehicle.Speed</code>, <code>Vehicle.Powertrain.TractionBattery.StateOfCharge</code>).</li>\n<li><strong>Beziehungen & Stereotypen:</strong></li>\n<li><strong>Dekompositionskanten mit ausgefülltem Endpunkt (Solid Dot / Mandatory Feature):</strong> Beide Sub-Features sind obligatorisch an das Parent-Feature gebunden.</li>\n<li><strong>Kardinalität/Bindung:</strong> Eine Konformität zu <code>FO_TR_FEAT_00202</code> bedingt zwingend die simultane Unterstützung von Datenmodell (<code>VSS</code>) <strong>und</strong> API-/Protokollschicht (<code>VISS</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Modell:</strong> Das Diagramm selbst enthält keine Ablaufsemantik, definiert jedoch die Systemarchitektur für folgende Laufzeitinteraktionen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Request-Handling:</strong> Ein Client (z. B. Adaptive Application oder Cloud-Agent) initiiert einen VISS-konformen Request (z. B. WebSocket-Payload).</li>\n<li><strong>Namensraum-Auflösung:</strong> Der Request referenziert den standardisierten VSS-Pfad. Der VISS-Provider/Server validiert den Pfad gegen den VSS-Katalog.</li>\n<li><strong>Plattform-Mapping:</strong> Der VISS-Server übersetzt den VSS-Datenpunkt intern auf AUTOSAR-native Kommunikationsmechanismen (<code>ara::com</code> Service-Interfaces, SOME/IP-Events, IPC oder Gateway-Mappings zu Classic-PDU-Signalen).</li>\n<li><strong>Response / Event-Stream:</strong> Asynchrone Rückmeldung oder zyklisches Publish/Subscribe über die VISS-Session an den Client.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>System- und Applikationsdesign:</strong></li>\n<li><code>Automotive_API</code> kann nicht fragmentiert umgesetzt werden: Entwickler dürfen VISS nicht mit proprietären Signalbezeichnungen betreiben, wenn AUTOSAR-Konformität zu <code>FEAT_00202</code> gefordert ist; die Semantik muss vollständig auf dem VSS-Baum basieren.</li>\n<li>Für Adaptive-Applikationen dient die Kombination aus VISS/VSS als standardisierte Abstraktionsschicht oberhalb von <code>ara::com</code>, um Applikationslogik unabhängig von OEM-spezifischen CAN/LIN/SOME/IP-Matrixen zu halten.</li>\n<li><strong>Konfiguration & Integration:</strong></li>\n<li><strong>Signal-to-Service Mapping:</strong> Ein Mapping-Layer zwischen ARXML-Signalen/Systembeschreibungen und dem VSS-Baum ist zwingend erforderlich (VSS-Mapper-Komponente auf HPC/Adaptive-Knoten).</li>\n<li><strong>Security & Access Management:</strong> VISS spezifiziert granulare Zugriffssteuerungen (Token/OAuth-basiert), die mit dem AUTOSAR Identity and Access Management (<code>ara::iam</code> / Crypto-Stack) harmonisiert werden müssen, um unberechtigten Zugriff auf steuernde VSS-Aktorikpfade zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-0285c6fe8b3b7f2d", "to": "FIG-c2d2cd29b330d8c8", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
